package com.hotel.dao.impl;
import com.hotel.dao.UserDao; import com.hotel.exception.DataAccessException; import com.hotel.model.User; import com.hotel.util.DBConnection; import java.sql.*; import java.util.Optional;
public class UserDaoImpl implements UserDao { public Optional<User> findByEmail(String email){String sql="SELECT user_id,email,password_hash,full_name,role_code,status_code FROM dbo.[users] WHERE email=?";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(sql)){p.setString(1,email);try(ResultSet r=p.executeQuery()){if(!r.next())return Optional.empty();User u=new User();u.setUserId(r.getLong(1));u.setEmail(r.getString(2));u.setPasswordHash(r.getString(3));u.setFullName(r.getString(4));u.setRoleCode(r.getString(5));u.setStatusCode(r.getString(6));return Optional.of(u);}}catch(SQLException e){throw new DataAccessException("Unable to load account",e);}} }
